// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(address attacker, uint256 amount) public {
        vm.assume(attacker != address(this));
        vm.assume(attacker != address(0));
        amount = bound(amount, 1, address(c).balance + 1e18);
        vm.deal(address(c), amount);
        uint256 balanceBefore = address(c).balance;
        vm.prank(attacker);
        try c.withdrawAll(attacker) { } catch { }
        uint256 balanceAfter = address(c).balance;
        assertTrue(balanceAfter == balanceBefore);
    }
}
